#include "AddMaterialDialog.hpp"
#include "ui_AddMaterialDialog.h" // file generated by the MOC

#include <string>
#include <fmt/core.h>


AddMaterialDialog::AddMaterialDialog(QWidget* parent)
: QDialog(parent)
, ui(new Ui::AddMaterialDialog) // class denefinition generated by the MOC
{
  ui->setupUi(this);

  m_doubleValidator.setBottom(0.0);

  for (int i = 1; i < 10; ++i)
  {
    auto* layoutItem = ui->materialFormLayout->itemAt(i, QFormLayout::ItemRole::FieldRole);
    auto* widget = layoutItem->widget();
    auto* lineEdit = qobject_cast<QLineEdit*>(widget);

    if (!lineEdit)
    {
      fmt::println(stderr, "This line edit is ass.");
    }

    lineEdit->setValidator(&m_doubleValidator);
  }

  connect(ui->importMaterialButton, &QPushButton::clicked, this, &AddMaterialDialog::onImportMaterialButtonClicked);
}


AddMaterialDialog::~AddMaterialDialog()
{
}


void AddMaterialDialog::accept()
{
  // TODO: MAKE WORK!!!!
  m_material.description = ui->nameLineEdit->text().toStdString();
  m_material.absorptionCoefficient = std::ui->absorptionCoefficientLineEdit->text().toStdString();
  m_material.thermalExpansionCoefficient;
  m_material.thermoOpticCoefficent;
  m_material.thermalconductivity;
  m_material.specificHeatCapacity;
  m_material.refractiveIndex;        
  m_material.youngsModulus;
  m_material.poissonRatio;
  m_material.mechanicalLoss;

  QDialog::accept();

  fmt::println("Name: {}", m_material.description);
}


